"use client";

/**
 * Status pill: one centred sentence with a pill inside it that rolls through
 * its states, each with its own icon and colour, until the last one lands.
 *
 * Written by Better Design. Painted from the theme prop: the first state takes
 * the muted ink, the middle ones the primary, the last a green turned from it.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import type { ReactNode } from "react";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { easings, mix, pickFont, progress, shiftHue, useVideoTheme, type VideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["600"], subsets: ["latin"] });

const FIRST_CHANGE = 36;
/** Frames between two state changes. */
const STEP = 40;
const ROLL_FRAMES = 14;

export interface StatusPillProps {
  /** The sentence. `{status}` marks where the pill sits; without it the pill ends the line. */
  line?: string;
  /** The states the pill rolls through, in order. The last one holds. */
  states?: string[];
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

type Kind = "wait" | "run" | "done";

const kindOf = (i: number, n: number): Kind => (i === n - 1 ? "done" : i === 0 ? "wait" : "run");

function Icon({ kind, color, mark, frame, draw }: { kind: Kind; color: string; mark: string; frame: number; draw: number }) {
  const common = { width: "0.78em", height: "0.78em", viewBox: "0 0 24 24", fill: "none", stroke: color, strokeWidth: 2.6, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };
  if (kind === "wait") {
    return (
      <svg {...common}>
        <circle cx="12" cy="12" r="9" />
        <path d="M12 7v5l3 2" />
      </svg>
    );
  }
  if (kind === "run") {
    return (
      <svg {...common} style={{ transform: `rotate(${frame * 11}deg)` }}>
        <circle cx="12" cy="12" r="9" stroke={withAlpha(color, 0.25)} />
        <path d="M12 3a9 9 0 0 1 9 9" />
      </svg>
    );
  }
  return (
    <svg {...common}>
      <circle cx="12" cy="12" r="10" fill={color} stroke="none" />
      <path d="M7.5 12.5l3 3 6-6.5" stroke={mark} strokeDasharray="16" strokeDashoffset={16 * (1 - draw)} />
    </svg>
  );
}

/** A sentence whose inline status pill rolls from state to state. */
export function StatusPill({
  line = "Your export is {status}",
  states = ["Queued", "Running", "Done"],
  theme: themeOverride,
  font,
}: StatusPillProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);
  const list = states.length > 0 ? states : ["Done"];
  const n = list.length;

  const [before, after = ""] = line.includes("{status}") ? line.split("{status}") : [`${line} `, ""];
  const colorOf = (i: number): string => {
    const kind = kindOf(i, n);
    return kind === "wait" ? theme.mutedForeground : kind === "run" ? theme.primary : shiftHue(theme.primary, -110);
  };

  // Roll position: 0 shows the first state, n - 1 the last.
  let roll = 0;
  for (let k = 0; k < n - 1; k++) roll += easings.out(progress(frame, FIRST_CHANGE + k * STEP, ROLL_FRAMES));
  const low = Math.floor(roll);
  const color = mix(colorOf(low), colorOf(Math.min(n - 1, low + 1)), roll - low);

  // The pill's width follows the state on show. Inter's semibold runs near 0.6em a letter.
  const widthOf = (i: number): number => 0.78 + 0.32 + 0.6 * list[i].length;
  const width = widthOf(low) + (widthOf(Math.min(n - 1, low + 1)) - widthOf(low)) * (roll - low);

  const lastAt = FIRST_CHANGE + (n - 2) * STEP;
  const pop = n > 1 ? interpolate(frame, [lastAt + 6, lastAt + 12, lastAt + 24], [0, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) : 0;
  const draw = n > 1 ? easings.out(progress(frame, lastAt + 6, 14)) : easings.out(progress(frame, 10, 14));

  const enter = easings.out(progress(frame, 0, 18));
  const pillIn = easings.overshoot(progress(frame, 6, 18));

  const text = (value: string): ReactNode => (value.trim() ? <span style={{ whiteSpace: "pre" }}>{value}</span> : null);

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div
        style={{
          maxWidth: 1600,
          textAlign: "center",
          fontSize: 96,
          fontWeight: 600,
          letterSpacing: "-0.035em",
          lineHeight: 1.25,
          color: theme.foreground,
          opacity: enter,
          transform: `translateY(${(1 - enter) * 22}px)`,
        }}
      >
        {text(before)}
        <span
          style={{
            display: "inline-grid",
            boxSizing: "border-box",
            verticalAlign: "middle",
            margin: "0 0.1em",
            fontSize: "0.66em",
            letterSpacing: "-0.02em",
            padding: "0 0.5em",
            width: `${width + 1}em`,
            height: "1.5em",
            borderRadius: 999,
            overflow: "hidden",
            background: withAlpha(color, 0.13),
            boxShadow: `inset 0 0 0 2px ${withAlpha(color, 0.3)}`,
            color,
            transform: `scale(${pillIn * (1 + 0.06 * pop)})`,
          }}
        >
          {list.map((state, i) => {
            const offset = i - roll;
            return (
              <span
                key={`${state}-${i}`}
                style={{
                  gridArea: "1 / 1",
                  display: "flex",
                  alignItems: "center",
                  gap: "0.32em",
                  whiteSpace: "nowrap",
                  transform: `translateY(${offset * 1.5}em)`,
                  opacity: Math.max(0, 1 - Math.abs(offset)),
                  color: colorOf(i),
                }}
              >
                <Icon kind={kindOf(i, n)} color={colorOf(i)} mark={theme.primaryForeground} frame={frame} draw={draw} />
                {state}
              </span>
            );
          })}
        </span>
        {text(after)}
      </div>
    </AbsoluteFill>
  );
}
